sys_script_include.script:
var FleetReservationAjax = Class.create();
FleetReservationAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    /**
     * FLEET-30: portal "Check Availability" - runs FleetReservationValidator on the posted values.
     * Params: sysparm_sys_id, sysparm_requested_by, sysparm_assigned_driver, sysparm_requested_depot,
     *         sysparm_vehicle_category, sysparm_start, sysparm_end (UTC yyyy-MM-dd HH:mm:ss)
     * Returns JSON {valid: boolean, errors: []}
     */
    validateRequest: function() {
        var res = new GlideRecord('x_1850693_enterp_0_reservation');
        var id = this.getParameter('sysparm_sys_id');
        if (!(id && res.get(id))) {
            res.initialize();
            res.setValue('requested_by', this.getParameter('sysparm_requested_by') || gs.getUserID());
        }
        var map = {
            assigned_driver: 'sysparm_assigned_driver',
            requested_depot: 'sysparm_requested_depot',
            vehicle_category: 'sysparm_vehicle_category',
            start_datetime: 'sysparm_start',
            end_datetime: 'sysparm_end'
        };
        for (var f in map) {
            var v = this.getParameter(map[f]);
            if (v) {
                res.setValue(f, v);
            }
        }
        var errors = new FleetReservationValidator().validate(res);
        return JSON.stringify({ valid: errors.length === 0, errors: errors });
    },

    type: 'FleetReservationAjax'
});
